const StorageModule = (() => {
  let data = {};

  return {
    set(key, value) {
      data[key] = value;
    },
    get(key) {
      return data[key];
    },
    remove(key) {
      delete data[key];
    },
    clear() {
      data = {};
    },
    getAll() {
      return { ...data };
    }
  };
})();

const ValidatorModule = (() => {
  const rules = {
    email: (v) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v),
    required: (v) => v !== undefined && v !== null && v !== "",
    minLength: (min) => (v) => v.length >= min,
    maxNumber: (max) => (v) => typeof v === "number" && v <= max
  };

  return {
    validate(data, schema) {
      const errors = {};
      for (const [field, fieldRules] of Object.entries(schema)) {
        const rulesArray = Array.isArray(fieldRules) ? fieldRules : [fieldRules];
        for (const rule of rulesArray) {
          const validateFn = typeof rule === "function" ? rule : rules[rule];
          if (validateFn && !validateFn(data[field])) {
            errors[field] = errors[field] || [];
            errors[field].push(`Validation failed for ${field}`);
          }
        }
      }
      return { isValid: Object.keys(errors).length === 0, errors };
    },
    addRule(name, fn) {
      rules[name] = fn;
    }
  };
})();

const PluginSystem = (() => {
  const plugins = new Map();

  return {
    register(name, plugin) {
      plugins.set(name, plugin);
    },
    execute(hook, data) {
      const results = [];
      for (const [name, plugin] of plugins) {
        if (plugin[hook]) {
          results.push(plugin[hook](data));
        }
      }
      return results;
    },
    unregister(name) {
      plugins.delete(name);
    }
  };
})();

const App = (() => {
  let initialized = false;

  return {
    init(config = {}) {
      if (initialized) return;
      PluginSystem.execute("init", config);
      initialized = true;
      console.log("App initialized");
    },
    run() {
      if (!initialized) throw new Error("App not initialized");
      PluginSystem.execute("run", null);
      console.log("App running");
    },
    shutdown() {
      PluginSystem.execute("shutdown", null);
      StorageModule.clear();
      initialized = false;
      console.log("App shut down");
    }
  };
})();

export { StorageModule, ValidatorModule, PluginSystem, App };
